function syncColumnWidths(
  headers: HTMLTableCellElement[],
  rows: HTMLTableRowElement[],
) {
  for (const row of rows) {
    headers.forEach((th, i) => {
      row.cells[i].style.width = `${th.offsetWidth}px`; // read after a write
    });
  }
}

function syncColumnWidths(
  headers: HTMLTableCellElement[],
  rows: HTMLTableRowElement[],
) {
  const widths = headers.map((th) => th.offsetWidth); // all reads first
  for (const row of rows) {
    widths.forEach((w, i) => {
      row.cells[i].style.width = `${w}px`; // then only writes
    });
  }
}

